package com.smartdoc.ai.provider;
import java.net.*; import java.util.*;
public final class ProviderUrlPolicy { private final boolean allowLoopback,allowPrivate; public ProviderUrlPolicy(boolean l,boolean p){allowLoopback=l;allowPrivate=p;}
 public String validateAndNormalize(String raw){try{if(raw==null||raw.length()>500)throw invalid();URI uri=new URI(raw.trim());String scheme=uri.getScheme(),host=uri.getHost();if(host==null||uri.getUserInfo()!=null||uri.getFragment()!=null||uri.getQuery()!=null)throw invalid();boolean loop=host.equalsIgnoreCase("localhost")||host.equals("127.0.0.1")||host.equals("::1");if(!"https".equalsIgnoreCase(scheme)&&!("http".equalsIgnoreCase(scheme)&&loop&&allowLoopback))throw invalid();for(InetAddress address:InetAddress.getAllByName(host)){if(isLocal(address)&&!allowLoopback)throw invalid();if(isPrivate(address)&&!allowPrivate)throw invalid();}String path=uri.getRawPath()==null?"":uri.getRawPath();String normalized=new URI(uri.getScheme().toLowerCase(Locale.ROOT),null,host.toLowerCase(Locale.ROOT),uri.getPort(),path,null,null).toString();return normalized.replaceAll("/+$","");}catch(UnknownHostException e){throw new IllegalArgumentException("Provider URL host cannot be resolved");}catch(URISyntaxException|IllegalArgumentException e){throw e instanceof IllegalArgumentException?(IllegalArgumentException)e:invalid();}}
 private static boolean isLocal(InetAddress a){return a.isLoopbackAddress();} private static boolean isPrivate(InetAddress a){return a.isAnyLocalAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress()||a.getHostAddress().startsWith("169.254.");} private static IllegalArgumentException invalid(){return new IllegalArgumentException("Provider URL is not permitted");}
}
